int vu1NativeRun(VU1Interpreter &vu, VuNativeCtx &c)
{
    while (vu.m_cycle < c.budgetEnd && !vu.m_stopRequested)
    {
        const uint32_t pc = vu.m_state.pc;
        if ((pc & 7u) != 0u || pc >= 0x4000u)
            return 2;
        const StepFn fn = kStep[pc >> 3];
        if (!fn)
            return 2;
        const int r = fn(vu, c);
        if (r != 0)
            return r;
    }
    return 1;
}
